\begin{tikzpicture}[font=\sffamily, line width=0.8pt]
  % axes: 1 cm per ms; potential scaled so -80 mV is at y = 0
  \draw (0,0) -- (6.3,0);
  \draw (0,0) -- (0,5.2);
  % time ticks and labels
  \foreach \t in {0,1,...,6} {
    \draw (\t,0) -- (\t,-0.1);
    \node[below] at (\t,-0.1) {\small \t};
  }
  % potential ticks and labels
  \foreach \v/\yy in {-80/0,-60/0.8,-40/1.6,-20/2.4,0/3.2,20/4.0,40/4.8} {
    \draw (0,\yy) -- (-0.1,\yy);
    \node[left] at (-0.1,\yy) {\small \v};
  }
  % axis titles
  \node at (3,-0.75) {Time / ms};
  \node[rotate=90] at (-1.0,2.4) {Membrane potential / mV};
  % action potential curve
  \draw[very thick] plot[smooth] coordinates {(0,0.4) (1,0.4) (1.4,1.2) (1.8,2.8) (2.2,4.2) (2.6,4.8) (2.9,4.4) (3.2,3.2) (3.5,2.0) (3.8,0.8) (4.1,0.2) (4.5,0) (5.0,0.2) (5.5,0.32) (6,0.4)};
  % stage labels with leader lines
  \draw[thin] (1.8,2.8) -- (1.2,3.9) node[left] {A};
  \draw[thin] (3.2,3.2) -- (3.8,4.6) node[right] {B};
  \draw[thin] (4.5,0) -- (4.5,-1.3) node[below] {C};
  \draw[thin] (5.5,0.32) -- (5.5,-1.3) node[below] {D};
  \node at (3,-2.0) {\textbf{Fig. 9.1}};
\end{tikzpicture}
